/**
 * The panel outside DeepSeek Harness: `mount` renders it into an element of another page, which reaches the management API
 * through a path it proxies (`base`), and may pass its own `fetch` (for example one that sends an expired sign-in back through
 * that page's login). It is read-only unless `readOnly: false`: such a page has no Session view, and a proxy that forwards
 * changes would hand DSH's control of the Host to whoever can open that page. The page has no DSH theme either, so the
 * panel brings the tokens its stylesheet reads (`standalone-theme.css`, generated by `scripts/standalone-theme.mjs`).
 *
 * Built by tsdown as `lib/standalone.js`, a script that bundles React and sets `window.DshSuperagentPanel`.
 */
import { createRoot } from 'react-dom/client'
import type { ApiOptions } from './api.ts'
import { App } from './app.tsx'
import { en, zh } from './locales.ts'
import THEME from './standalone-theme.css?raw'
import type { T } from './text.ts'

export interface StandaloneOptions extends ApiOptions {
  /** The language of the panel, `zh` unless given. */
  locale?: 'zh' | 'en'
}
/** The panel's words in one language, with `{name}` placeholders filled as DSH's locale fills them. */
export const translator = (dictionary: Record<string, string>): T => ((key: string, params?: Record<string, unknown>) => {
  const template = dictionary[key] ?? key
  return params ? template.replace(/\{(\w+)\}/g, (match, name: string) => name in params ? String(params[name]) : match) : template
}) as T
const noSession = async () => {}

/**
 * Renders the panel into `element`.
 * @returns a function that unmounts it.
 */
export function mount(element: HTMLElement, { locale = 'zh', readOnly = true, ...api }: StandaloneOptions): () => void {
  const root = createRoot(element)
  root.render(<>
    <style>{THEME}</style>
    <App t={translator(locale === 'en' ? en : zh)} openSession={noSession} deploymentForm={undefined} api={{ ...api, readOnly }} />
  </>)
  return () => { root.unmount() }
}

declare global { interface Window { DshSuperagentPanel?: { mount: typeof mount } } }
if (typeof window !== 'undefined') window.DshSuperagentPanel = { mount }
